// Package mevwatch implements mempool risk detection.
package mevwatch

import (
	"sort"
	"strconv"
)

// Swap is one observed swap in a pending or confirmed transaction.
type Swap struct {
	TxHash   string
	Pool     string
	Trader   string
	In       int64
	Out      int64
	GasPrice int64
	Index    int
}

// Finding is one risk conclusion with the evidence that produced it.
type Finding struct {
	TxHash   string
	Kind     string
	Severity int
	Evidence []string
}

// Detect flags sandwich and displacement patterns around one victim swap.
func Detect(swaps []Swap, victim string) []Finding {
	victimIndex := -1
	for index, swap := range swaps {
		if swap.TxHash == victim {
			victimIndex = index
			break
		}
	}
	if victimIndex <= 0 || victimIndex >= len(swaps)-1 {
		return nil
	}
	front, back := swaps[victimIndex-1], swaps[victimIndex+1]
	if front.Trader == back.Trader && front.Pool == back.Pool && front.Trader != swaps[victimIndex].Trader &&
		front.GasPrice > swaps[victimIndex].GasPrice && back.GasPrice > swaps[victimIndex].GasPrice {
		return []Finding{{
			TxHash: victim, Kind: "sandwich", Severity: 3,
			Evidence: []string{
				"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
				"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
				"victim gas " + strconv.FormatInt(swaps[victimIndex].GasPrice, 10),
			},
		}}
	}
	if front.GasPrice > swaps[victimIndex].GasPrice*2 {
		return []Finding{{TxHash: victim, Kind: "displacement", Severity: 2,
			Evidence: []string{"front gas dominates victim by more than 2x"}}}
	}
	return nil
}

// Rank orders findings by severity then hash.
func Rank(findings []Finding) []Finding {
	sorted := append([]Finding(nil), findings...)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Severity == sorted[j].Severity {
			return sorted[i].TxHash < sorted[j].TxHash
		}
		return sorted[i].Severity > sorted[j].Severity
	})
	return sorted
}

// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
package mevwatch

import (
	"fmt"
	"math"
)

// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
// Command 为字符串命令。
type LogEntry struct {
	Index   int    `json:"index"`
	Term    int    `json:"term"`
	Command string `json:"command"`
}

// InitialState 是跟随者在本次调用开始时的状态。
type InitialState struct {
	// CurrentTerm 是该节点已知的最新任期。
	CurrentTerm int `json:"currentTerm"`
	// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
	CommittedIndex int `json:"committedIndex"`
	// Log 是从索引 1 开始的连续日志。
	Log []LogEntry `json:"log"`
}

// AppendRequest 是顺序到达的一次日志复制请求。
type AppendRequest struct {
	// Term 是领导者任期。
	Term int `json:"term"`
	// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
	// 均为 0 表示日志起点（哨兵），不是真实条目。
	PrevLogIndex int `json:"prevLogIndex"`
	PrevLogTerm  int `json:"prevLogTerm"`
	// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
	Entries []LogEntry `json:"entries"`
	// LeaderCommit 是领导者已提交索引。
	LeaderCommit int `json:"leaderCommit"`
}

// AppendResult 是单条请求处理后节点对该请求的答复。
type AppendResult struct {
	// Accepted 表示本次复制是否成功。
	Accepted bool `json:"accepted"`
	// Reason 是成功 ok 或被拒绝的具体原因。
	Reason string `json:"reason"`
	// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
	Term int `json:"term"`
	// CommittedIndex 是处理后节点的已提交索引。
	CommittedIndex int `json:"committedIndex"`
	// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
	// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
	// 复制是否被接受与命令应用是否失败相互独立表达。
	AppliedIndex *int        `json:"appliedIndex,omitempty"`
	ApplyError   *ApplyError `json:"applyError,omitempty"`
	// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
	// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
	// 编解码规则见 applyfields.go。
	applyFields bool
}

// ReplicateOutput 是整次调用的结果。
type ReplicateOutput struct {
	// Results 与输入请求一一对应。
	Results []AppendResult `json:"results"`
	// FinalTerm / FinalCommittedIndex 是最终状态。
	FinalTerm           int `json:"finalTerm"`
	FinalCommittedIndex int `json:"finalCommittedIndex"`
	// FinalLog 是处理完所有请求后的完整日志。
	FinalLog []LogEntry `json:"finalLog"`
	// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
	// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
	// 反映初始已提交前缀的应用结果。
	FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
	FinalKV           map[string]string `json:"finalKV,omitempty"`
	FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
	// applyFields 含义同 AppendResult.applyFields，编解码规则见 applyfields.go。
	applyFields bool
}

// 拒绝原因（稳定标识符，帮助文档中有说明）。
const (
	ReasonOK                      = "ok"
	ReasonStaleTerm               = "stale term: leader term is lower than current term"
	ReasonRequestTermNegative     = "invalid request: term is negative"
	ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
	ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
	ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
	ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
	ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
	ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
	ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
	ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
	ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
	ReasonWouldOverwriteCommitted = "would overwrite committed entry"
)

type replicateState struct {
	currentTerm    int
	committedIndex int
	log            []LogEntry // log[i].Index == i+1
}

// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
type ReplicateOptions struct {
	// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete），在本次
	// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
	// 时命令仍是不加解释的任意字符串。
	ApplyKV bool
}

// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
	return ReplicateWithOptions(initial, requests, ReplicateOptions{})
}

// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
// 可选行为（如键值应用）。
func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
	state, err := newReplicateState(initial)
	if err != nil {
		return ReplicateOutput{}, err
	}

	var applier *kvApplier
	if opts.ApplyKV {
		applier = newKVApplier()
		// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
		applier.applyUpTo(state.log, state.committedIndex)
	}

	results := make([]AppendResult, 0, len(requests))
	for _, request := range requests {
		result := state.apply(request)
		if applier != nil {
			// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
			// 不改变复制的接受与否、提交位置或拒绝原因。
			applier.applyUpTo(state.log, state.committedIndex)
			result.setApplyFields(applier.appliedIndex, applier.err)
		}
		results = append(results, result)
	}
	finalLog := append([]LogEntry{}, state.log...)
	if finalLog == nil {
		finalLog = []LogEntry{}
	}
	output := ReplicateOutput{
		Results:             results,
		FinalTerm:           state.currentTerm,
		FinalCommittedIndex: state.committedIndex,
		FinalLog:            finalLog,
	}
	if applier != nil {
		output.setApplyFields(applier.appliedIndex, applier.kv, applier.err)
	}
	return output, nil
}

func newReplicateState(initial InitialState) (replicateState, error) {
	if initial.CurrentTerm < 0 {
		return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
	}
	if initial.CommittedIndex < 0 {
		return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
	}
	if initial.CommittedIndex > len(initial.Log) {
		return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
	}
	log := append([]LogEntry(nil), initial.Log...)
	if rule, i := checkEntryRules(log, 0, initial.CurrentTerm); rule != entryRuleOK {
		expected := i + 1
		entry := log[i]
		switch rule {
		case entryRuleIndexGap:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
		case entryRuleTermNonPositive:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
		case entryRuleTermDecreases:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
		case entryRuleTermExceedsMax:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
		}
	}
	return replicateState{
		currentTerm:    initial.CurrentTerm,
		committedIndex: initial.CommittedIndex,
		log:            log,
	}, nil
}

// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
func (s *replicateState) termAt(idx int) (term int, ok bool) {
	switch {
	case idx == 0:
		return 0, true
	case idx < 0 || idx > len(s.log):
		return 0, false
	default:
		return s.log[idx-1].Term, true
	}
}

// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
func (s *replicateState) apply(request AppendRequest) AppendResult {
	snapshot := *s
	accepted, reason := s.tryApply(request)
	if !accepted {
		// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
		s.log = snapshot.log
		s.committedIndex = snapshot.committedIndex
	}
	return AppendResult{
		Accepted:       accepted,
		Reason:         reason,
		Term:           s.currentTerm,
		CommittedIndex: s.committedIndex,
	}
}

func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
	// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
	// 状态——即使它携带更高任期，也不能更新节点。
	if reason := validateRequest(request); reason != ReasonOK {
		return false, reason
	}

	// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
	if request.Term < s.currentTerm {
		return false, ReasonStaleTerm
	}

	// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
	// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
	if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
		return false, ReasonEntryTermDecreases
	}

	// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
	// 任期更新也保留。
	if request.Term > s.currentTerm {
		s.currentTerm = request.Term
	}

	// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
	prevTerm, ok := s.termAt(request.PrevLogIndex)
	if !ok || prevTerm != request.PrevLogTerm {
		return false, ReasonPrevLogMismatch
	}

	// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
	// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
	// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
	// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
	// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
	start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
	cutAt := -1                   // 首个任期不同的现有位置（切片下标）
	matched := 0
	for offset, incoming := range request.Entries {
		idx := start + 1 + offset
		if idx > len(s.log) {
			break // 该位置及之后都不存在：稍后整体追加
		}
		existing := s.log[idx-1]
		switch {
		case existing.Term == incoming.Term && existing.Command == incoming.Command:
			// 完全相同：保留，重复请求不会产生重复条目。
			matched++
		case existing.Term == incoming.Term:
			// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
			return false, ReasonCommandConflictSameTerm
		case idx <= s.committedIndex:
			// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
			return false, ReasonWouldOverwriteCommitted
		default:
			// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
			cutAt = idx - 1
		}
		if cutAt >= 0 {
			break
		}
	}

	// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
	// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
	if cutAt >= 0 {
		matched = cutAt - start
		s.log = append([]LogEntry(nil), s.log[:cutAt]...)
	}
	if matched < len(request.Entries) {
		s.log = append(s.log, request.Entries[matched:]...)
	}

	// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
	// 且不会后退。空条目请求的确认位置就是前一条索引。
	lastIndex := request.PrevLogIndex + len(request.Entries)
	newCommit := request.LeaderCommit
	if lastIndex < newCommit {
		newCommit = lastIndex
	}
	if newCommit > s.committedIndex {
		s.committedIndex = newCommit
	}
	return true, ReasonOK
}

func validateRequest(request AppendRequest) string {
	if request.Term < 0 {
		return ReasonRequestTermNegative
	}
	if request.PrevLogIndex < 0 {
		return ReasonPrevLogIndexNegative
	}
	if request.PrevLogTerm < 0 {
		return ReasonPrevLogTermNegative
	}
	if request.LeaderCommit < 0 {
		return ReasonLeaderCommitNegative
	}
	// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
	// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
	// tryApply 中单独检查。
	switch rule, _ := checkEntryRules(request.Entries, request.PrevLogIndex, request.Term); rule {
	case entryRuleIndexGap:
		return ReasonEntryIndexGap
	case entryRuleTermNonPositive:
		return ReasonEmptyEntryTerm
	case entryRuleTermDecreases:
		return ReasonEntryTermDecreases
	case entryRuleTermExceedsMax:
		return ReasonEntryTermExceedsReqTerm
	}
	return ReasonOK
}

// entryRule 是日志条目序列共有校验发现的违规类别。初始日志与复制请求条目
// 共用同一套规则（见 checkEntryRules），各自把类别翻译成自己的错误表达。
type entryRule int

const (
	entryRuleOK entryRule = iota
	// entryRuleIndexGap：索引未从期望位置连续排列（含下一位置超出 int 上限）。
	entryRuleIndexGap
	// entryRuleTermNonPositive：任期非正。
	entryRuleTermNonPositive
	// entryRuleTermDecreases：任期低于序列内前一条目。
	entryRuleTermDecreases
	// entryRuleTermExceedsMax：任期超过调用方给定的上限。
	entryRuleTermExceedsMax
)

// checkEntryRules 按条目顺序校验 entries 是否从 prevPosition+1 开始连续编号、
// 任期为正、沿序列自身不下降且不超过 maxTerm，返回首个违规的类别与该条目在
// entries 中的下标；全部通过时返回 entryRuleOK 与 -1。与序列之前一条日志
// （prevLogTerm）的任期衔接不属于本函数职责，由调用方单独检查。
//
// 位置必须用检查过的加法逐条推进：prevPosition+1 或链上任一后续位置超过当前
// int 上限时，输入里的负索引恰好在数学上等于回绕后的位置，直接相加会静默溢出
// 把它误判为连续。这种情况按索引不连续处理。空条目序列不要求存在下一位置，
// 最后一条恰好到达 int 上限同样合法。索引 0 是哨兵，真实条目索引必为正。
func checkEntryRules(entries []LogEntry, prevPosition, maxTerm int) (entryRule, int) {
	position := prevPosition
	for i, entry := range entries {
		if position == math.MaxInt {
			return entryRuleIndexGap, i // 下一位置无法用 int 表示
		}
		position++
		if entry.Index <= 0 || entry.Index != position {
			return entryRuleIndexGap, i
		}
		if entry.Term <= 0 {
			return entryRuleTermNonPositive, i
		}
		if i > 0 && entry.Term < entries[i-1].Term {
			return entryRuleTermDecreases, i
		}
		if entry.Term > maxTerm {
			return entryRuleTermExceedsMax, i
		}
	}
	return entryRuleOK, -1
}

// 结果 JSON 中键值应用字段的编解码规则。逐条请求结果（AppendResult）与整次
// 调用结果（ReplicateOutput）两层共用本文件的同一套约定，避免两处各自实现
// 导致行为漂移。本文件只做纯逻辑处理。
package mevwatch

import (
	"bytes"
	"encoding/json"
)

// 两层结果共用的应用字段规则：
//
// 输出：是否输出应用字段由该层结果上的应用字段开关（applyFields）决定，
// 开关只在启用键值应用（ReplicateOptions.ApplyKV）的结果上打开。开关关闭
// 时应用字段整体缺省（字段上的 omitempty 生效，命令按任意字符串处理的原
// 有输出形状不变）；开关打开时该层全部应用字段强制输出，零值照常出现——
// 索引为 0 输出 0、空键值表输出 {}、无错误输出 null，不因值为空而省略。
//
// 填充：开启键值应用时，每条结果必须填已应用索引与应用错误，最终结果必须
// 填已应用索引、键值表与应用错误；没有复制请求时最终结果同样反映初始已
// 提交前缀的应用状态。
//
// 读入：按该层 JSON 中是否出现任一应用字段恢复开关，判定与解码接受的键名
// 规则一致：字段名只改字母大小写（如 "ApplyError"、"FINALKV"）也按出现处理，
// 与其值是否为空无关；与应用字段名只是相似的无关键不触发。出现任一字段即视
// 为启用应用的结果，再次输出时带上该层完整应用字段；完全未出现则不补上。
// 两层各自独立判断，互不推断。读入会用解码出的新值完整替换结果对象，不残留
// 上一次读入的键值表、应用位置或错误；JSON 无法解析或字段类型不合法照常返回
// 解码错误，结果对象保持读入前的内容，不会把错误内容当作零值接受。

// appendResultApplyKeys 是 AppendResult 一层用于判定应用字段是否出现的键名。
var appendResultApplyKeys = []string{"appliedIndex", "applyError"}

// replicateOutputApplyKeys 是 ReplicateOutput 一层用于判定应用字段是否出现的键名。
var replicateOutputApplyKeys = []string{"finalAppliedIndex", "finalKV", "finalApplyError"}

// marshalApplyFields 按开关选择输出形状：开关关闭时编码 plain（应用字段因
// omitempty 整体缺省）；开关打开时编码 forced（应用字段以零值兜底全部出现）。
func marshalApplyFields(plain any, applyFields bool, forced any) ([]byte, error) {
	if !applyFields {
		return json.Marshal(plain)
	}
	return json.Marshal(forced)
}

// unmarshalApplyFields 把 data 解码到 dst 指向的别名对象，并报告 data 中是否
// 出现 keys 里的任一应用字段键。解码成功时 *dst 被新值完整替换，不残留此前
// 读入的应用状态；JSON 无法解析或字段类型不合法时返回错误，*dst 保持不变。
func unmarshalApplyFields[T any](data []byte, dst *T, keys []string) (present bool, err error) {
	var decoded T
	if err := json.Unmarshal(data, &decoded); err != nil {
		return false, err
	}
	present, err = jsonHasAnyKey(data, keys...)
	if err != nil {
		return false, err
	}
	*dst = decoded
	return present, nil
}

// jsonHasAnyKey 报告 JSON 对象中是否出现任一给定键。判定与 encoding/json
// 解码时的字段匹配规则一致：键名比较按 Unicode 大小写折叠（等价于
// bytes.EqualFold），因此只改字母大小写的应用字段名（如 "ApplyError"）
// 同样算出现；与字段名只是相似的其他键不会命中。
func jsonHasAnyKey(data []byte, keys ...string) (bool, error) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return false, err
	}
	for presentKey := range raw {
		for _, key := range keys {
			if bytes.EqualFold([]byte(presentKey), []byte(key)) {
				return true, nil
			}
		}
	}
	return false, nil
}

// derefInt 返回指针指向的索引值，nil 按 0 处理（强制输出时的零值兜底）。
func derefInt(p *int) int {
	if p == nil {
		return 0
	}
	return *p
}

// nonNilStringMap 把 nil 键值表替换为空表，保证强制输出时得到 {} 而不是 null。
func nonNilStringMap(kv map[string]string) map[string]string {
	if kv == nil {
		return map[string]string{}
	}
	return kv
}

// setApplyFields 填充单条请求结果的应用字段并打开该层的应用字段开关：
// 处理本请求后已应用的最高日志索引与首个应用错误（无错误为 nil）。
func (r *AppendResult) setApplyFields(appliedIndex int, applyErr *ApplyError) {
	r.AppliedIndex = &appliedIndex
	r.ApplyError = applyErr
	r.applyFields = true
}

// setApplyFields 填充整次调用结果的应用字段并打开该层的应用字段开关：
// 最终已应用的最高日志索引、最终键值表与首个应用错误（无错误为 nil）。
func (o *ReplicateOutput) setApplyFields(appliedIndex int, kv map[string]string, applyErr *ApplyError) {
	o.FinalAppliedIndex = &appliedIndex
	o.FinalKV = kv
	o.FinalApplyError = applyErr
	o.applyFields = true
}

// MarshalJSON 按共用规则输出应用字段：未启用键值应用时保持原有输出形状；
// 启用时强制输出 appliedIndex 与 applyError（索引 0 照常出现，无错误时为 null）。
func (r AppendResult) MarshalJSON() ([]byte, error) {
	type alias AppendResult
	return marshalApplyFields(alias(r), r.applyFields, struct {
		alias
		AppliedIndex int         `json:"appliedIndex"`
		ApplyError   *ApplyError `json:"applyError"`
	}{
		alias:        alias(r),
		AppliedIndex: derefInt(r.AppliedIndex),
		ApplyError:   r.ApplyError,
	})
}

// UnmarshalJSON 按共用规则读入应用字段：出现 appendResultApplyKeys 中任一键
// （键名只改字母大小写也算，与解码的字段匹配规则一致）即视为启用键值应用的
// 结果，再次编码会原样保留这些字段（含 0、null）；未出现时按未启用处理。
// 整个对象被完整替换，不会残留上一次读入的应用状态。字段类型错误照常返回
// 解码错误，结果保持读入前的内容。
func (r *AppendResult) UnmarshalJSON(data []byte) error {
	type alias AppendResult
	var decoded alias
	present, err := unmarshalApplyFields(data, &decoded, appendResultApplyKeys)
	if err != nil {
		return err
	}
	*r = AppendResult(decoded)
	r.applyFields = present
	return nil
}

// MarshalJSON 按共用规则输出应用字段：未启用键值应用时保持原有输出形状；
// 启用时强制输出 finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError
// （无错误为 null）。
func (o ReplicateOutput) MarshalJSON() ([]byte, error) {
	type alias ReplicateOutput
	return marshalApplyFields(alias(o), o.applyFields, struct {
		alias
		FinalAppliedIndex int               `json:"finalAppliedIndex"`
		FinalKV           map[string]string `json:"finalKV"`
		FinalApplyError   *ApplyError       `json:"finalApplyError"`
	}{
		alias:             alias(o),
		FinalAppliedIndex: derefInt(o.FinalAppliedIndex),
		FinalKV:           nonNilStringMap(o.FinalKV),
		FinalApplyError:   o.FinalApplyError,
	})
}

// UnmarshalJSON 按共用规则读入应用字段，语义同 AppendResult.UnmarshalJSON：
// 出现 replicateOutputApplyKeys 中任一键（键名只改字母大小写也算）时再次编码
// 保留 finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError（无错误为
// null）；未出现时整个对象被完整替换，不残留上一次读入的键值表、错误或应用
// 位置。Results 中每条请求结果由 AppendResult.UnmarshalJSON 各自恢复。字段
// 类型错误照常返回解码错误，结果保持读入前的内容。
func (o *ReplicateOutput) UnmarshalJSON(data []byte) error {
	type alias ReplicateOutput
	var decoded alias
	present, err := unmarshalApplyFields(data, &decoded, replicateOutputApplyKeys)
	if err != nil {
		return err
	}
	*o = ReplicateOutput(decoded)
	o.applyFields = present
	return nil
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
type replicateInput struct {
	CurrentTerm    int                      `json:"currentTerm"`
	CommittedIndex int                      `json:"committedIndex"`
	Log            []mevwatch.LogEntry      `json:"log"`
	ApplyKV        bool                     `json:"applyKV"`
	Requests       []mevwatch.AppendRequest `json:"requests"`
}

// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
func runReplicate() int {
	return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
}

func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
	data, err := io.ReadAll(stdin)
	if err != nil {
		fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
		return 1
	}
	var input replicateInput
	if err := json.Unmarshal(data, &input); err != nil {
		fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
		return 1
	}
	output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
		CurrentTerm:    input.CurrentTerm,
		CommittedIndex: input.CommittedIndex,
		Log:            input.Log,
	}, input.Requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
	if err != nil {
		fmt.Fprintf(stderr, "replicate: %v\n", err)
		return 1
	}
	encoded, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
		return 1
	}
	fmt.Fprintln(stdout, string(encoded))
	return 0
}

