375			{"negative commit", InitialState{CurrentTerm: 2, CommittedIndex: -1}, []string{"committedIndex"}},
376			{"commit beyond log", InitialState{CurrentTerm: 2, CommittedIndex: 2,
377				Log: []LogEntry{entry(1, 2, "a")}}, []string{"committedIndex", "exceeds"}},
378			{"index gap", InitialState{CurrentTerm: 2,
379				Log: []LogEntry{entry(2, 2, "a")}}, []string{"index"}},
380			{"zero term entry", InitialState{CurrentTerm: 2,
381				Log: []LogEntry{entry(1, 0, "a")}}, []string{"term"}},
382			{"decreasing terms", InitialState{CurrentTerm: 3,
383				Log: []LogEntry{entry(1, 3, "a"), entry(2, 2, "b")}}, []string{"term"}},
384			{"entry term beyond current", InitialState{CurrentTerm: 2,
385				Log: []LogEntry{entry(1, 3, "a")}}, []string{"currentTerm"}},
386		}
387		for _, tc := range cases {
388			t.Run(tc.name, func(t *testing.T) {
389				expectError(t, tc.initial, nil, tc.fragments...)
390			})
391		}
392	}
393	
394	func TestDeterministicJSONRoundTrip(t *testing.T) {
395		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}}
396		requests := []AppendRequest{
397			{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 2,
398				Entries: []LogEntry{entry(2, 3, "b")}},
399			{Term: 2, PrevLogIndex: 2, PrevLogTerm: 3}, // stale term
400		}
401		first, err := Replicate(initial, requests)
402		if err != nil {
403			t.Fatal(err)
404		}
405		second, err := Replicate(initial, requests)
406		if err != nil {
407			t.Fatal(err)
408		}
409		if !reflect.DeepEqual(first, second) {
410			t.Fatalf("non-deterministic output:\n%+v\n%+v", first, second)
411		}
412		encoded, err := json.Marshal(first)
413		if err != nil {
414			t.Fatal(err)
415		}
416		var decoded ReplicateOutput
417		if err := json.Unmarshal(encoded, &decoded); err != nil {
418			t.Fatal(err)
419		}
420		if !reflect.DeepEqual(decoded, first) {
421			t.Fatalf("JSON round trip mismatch:\n%+v\n%+v", decoded, first)
422		}
423	}
424	
425	func TestSequentialScenario(t *testing.T) {
426		// 经典场景：领导者连续发送，中间夹一次旧领导者的低任期请求。
427		out := run(t, InitialState{CurrentTerm: 1},
428			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
429				Entries: []LogEntry{entry(1, 1, "set x=1"), entry(2, 1, "set y=2")}},
430			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 2,
431				Entries: []LogEntry{entry(3, 2, "set z=3")}},
432			AppendRequest{Term: 1, PrevLogIndex: 3, PrevLogTerm: 2}, // 旧领导者，低任期
433			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2, LeaderCommit: 3},
434		)
435		statuses := []bool{true, true, false, true}
436		for i, result := range out.Results {
437			if result.Accepted != statuses[i] {
438				t.Fatalf("result %d = %+v, want accepted=%v", i, result, statuses[i])
439			}
440		}
441		if out.Results[2].Term != 2 {
442			t.Fatalf("stale request changed term: %d", out.Results[2].Term)
443		}
444		want := []LogEntry{entry(1, 1, "set x=1"), entry(2, 1, "set y=2"), entry(3, 2, "set z=3")}
445		if !reflect.DeepEqual(out.FinalLog, want) {
446			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
447		}
448		if out.FinalCommittedIndex != 3 {
449			t.Fatalf("final commit = %d, want 3", out.FinalCommittedIndex)
450		}
451	}
452	
453	// 首条位置越过 int 上限：prevLogIndex 取 MaxInt、非空条目的首条索引以最小负值
454	// 给出（恰好是回绕后的位置）。这是字段错误，按条目索引不连续拒绝：任期、提交
455	// 位置与日志都保持请求前状态，不能借高任期抬高节点任期。
456	func TestEntryIndexOverflowAtFirstPositionIsFieldError(t *testing.T) {
457		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
458			Log: []LogEntry{entry(1, 2, "a")}}
459		out := run(t, initial,
460			AppendRequest{Term: 9, PrevLogIndex: math.MaxInt, PrevLogTerm: 0, LeaderCommit: 0,
461				Entries: []LogEntry{entry(math.MinInt, 9, "x")}},
462		)
463		result := out.Results[0]
464		if result.Accepted || !strings.Contains(result.Reason, "not consecutive") {
465			t.Fatalf("expected index-gap field error, got %+v", result)
466		}
467		if result.Term != 2 || result.CommittedIndex != 1 {
468			t.Fatalf("field error changed state: %+v", result)
469		}
470		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
471			t.Fatalf("log changed: %+v", out.FinalLog)
472		}
473		if out.FinalTerm != 2 {
474			t.Fatalf("final term changed: %d", out.FinalTerm)
475		}
476	}
477	
478	// 高任期溢出非法请求不能影响后续合法请求：第二条任期 3 的合法追加正常接受，
479	// 最终任期为 3，原有已提交条目保留，提交位置随第二条推进。
480	func TestOverflowFieldErrorDoesNotPoisonLaterRequest(t *testing.T) {
481		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
482			Log: []LogEntry{entry(1, 2, "a")}}
483		out := run(t, initial,
484			AppendRequest{Term: 9, PrevLogIndex: math.MaxInt, PrevLogTerm: 0,
485				Entries: []LogEntry{entry(math.MinInt, 9, "x")}},
486			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 2,
487				Entries: []LogEntry{entry(2, 3, "b")}},
488		)
489		if out.Results[0].Accepted || !strings.Contains(out.Results[0].Reason, "not consecutive") {
490			t.Fatalf("first request should be an index-gap field error, got %+v", out.Results[0])
491		}
492		if out.Results[0].Term != 2 {
493			t.Fatalf("term should stay 2, got %d", out.Results[0].Term)
494		}
495		if !out.Results[1].Accepted || out.Results[1].Reason != ReasonOK {
496			t.Fatalf("valid request after field error rejected: %+v", out.Results[1])
497		}
498		if out.FinalTerm != 3 || out.FinalCommittedIndex != 2 {
499			t.Fatalf("unexpected final state: term=%d ci=%d", out.FinalTerm, out.FinalCommittedIndex)
500		}
501		want := []LogEntry{entry(1, 2, "a"), entry(2, 3, "b")}
502		if !reflect.DeepEqual(out.FinalLog, want) {
503			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
504		}
505	}
506	
507	// 溢出点在链中间：首条索引恰好为 MaxInt 合法，下一位置无法表示即整体字段错误，
508	// 即使输入的第二个索引恰好是回绕后的 MinInt。
509	func TestEntryIndexOverflowMidChainIsFieldError(t *testing.T) {
510		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
511			Log: []LogEntry{entry(1, 2, "a")}}
512		out := run(t, initial,
513			AppendRequest{Term: 9, PrevLogIndex: math.MaxInt - 1, PrevLogTerm: 0,
514				Entries: []LogEntry{entry(math.MaxInt, 9, "x"), entry(math.MinInt, 9, "y")}},
515		)
516		result := out.Results[0]
517		if result.Accepted || !strings.Contains(result.Reason, "not consecutive") {
518			t.Fatalf("expected index-gap field error, got %+v", result)
519		}
520		if result.Term != 2 || result.CommittedIndex != 1 {
521			t.Fatalf("field error changed state: %+v", result)
522		}
523		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
524			t.Fatalf("log changed: %+v", out.FinalLog)
525		}
526	}
527	
528	// 大索引本身不是字段非法：entries 为空时 prevLogIndex 取 MaxInt 也不要求存在
529	// 下一位置；非空请求最后条目恰好到达 MaxInt 同样合法。两者前置位置都不在本地
530	// 日志中，按原有的前缀不匹配规则拒绝，并保留较高任期更新。
531	func TestLargeRepresentableIndexesRemainLegalPrefixMismatch(t *testing.T) {
532		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
533			Log: []LogEntry{entry(1, 2, "a")}}
534		out := run(t, initial,
535			// 空条目心跳：不要求下一条索引存在。
536			AppendRequest{Term: 7, PrevLogIndex: math.MaxInt, PrevLogTerm: 0},
537			// 非空请求，最后一条恰好到达 MaxInt。
538			AppendRequest{Term: 8, PrevLogIndex: math.MaxInt - 1, PrevLogTerm: 0,
539				Entries: []LogEntry{entry(math.MaxInt, 8, "z")}},
540		)
541		if out.Results[0].Accepted || !strings.Contains(out.Results[0].Reason, "prev log mismatch") {
542			t.Fatalf("empty MaxInt heartbeat should be prev mismatch, got %+v", out.Results[0])
543		}
544		if out.Results[0].Term != 7 {
545			t.Fatalf("term update should survive: %d", out.Results[0].Term)
546		}
547		if out.Results[1].Accepted || !strings.Contains(out.Results[1].Reason, "prev log mismatch") {
548			t.Fatalf("last-entry-at-MaxInt request should be prev mismatch, got %+v", out.Results[1])
549		}
550		if out.Results[1].Term != 8 {
551			t.Fatalf("term update should survive: %d", out.Results[1].Term)
552		}
553		if out.FinalTerm != 8 || out.FinalCommittedIndex != 1 || len(out.FinalLog) != 1 {
554			t.Fatalf("state changed: term=%d ci=%d log=%+v", out.FinalTerm, out.FinalCommittedIndex, out.FinalLog)
555		}
556	}
557	
558	// 任何非正的真实条目索引都是字段错误：哨兵之后首条索引不能为 0 或负值，
559	// 即使它在补码意义下等于某个回绕位置。
560	func TestNonPositiveEntryIndexIsFieldError(t *testing.T) {
561		initial := InitialState{CurrentTerm: 2}
562		cases := []AppendRequest{
563			{Term: 9, PrevLogIndex: 0, Entries: []LogEntry{entry(0, 9, "x")}},
564			{Term: 9, PrevLogIndex: 0, Entries: []LogEntry{entry(-1, 9, "x")}},
565			{Term: 9, PrevLogIndex: 1, Entries: []LogEntry{entry(0, 9, "x")}},
566		}
567		for i, request := range cases {
568			out := run(t, initial, request)
569			result := out.Results[0]
570			if result.Accepted || !strings.Contains(result.Reason, "not consecutive") {
571				t.Fatalf("case %d: expected index-gap field error, got %+v", i, result)
572			}
573			if result.Term != 2 {
574				t.Fatalf("case %d: term changed to %d", i, result.Term)
575			}
576		}
577	}
