func TestNonPositiveEntryIndexIsFieldError(t *testing.T) {
	initial := InitialState{CurrentTerm: 2}
	cases := []AppendRequest{
		{Term: 9, PrevLogIndex: 0, Entries: []LogEntry{entry(0, 9, "x")}},
